contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount_, uint256 rate_, uint256 duration_) public payable {
        require(rate_ <= 1e18);
        require(duration_ <= 365 days);
        require(amount_ <= 1e18, "amount too large");

        uint256 interest = c.interestFor(amount_, rate_, duration_); if (__ESBMC_reverted()) return;

        assert(interest == (amount_ * ((rate_ * duration_) / 365 days)) / 1e18);
    }

    receive() external payable {}
}

