pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount_, uint256 rate_, uint256 duration_) internal {
        vm.assume(rate_ <= 1e18);
        duration_ = bound(duration_, 0, 365);
        vm.assume(amount_ <= 1e18);
        uint256 interest;
        try c.interestFor(amount_, rate_, duration_) returns (uint256 __r) { interest = __r; } catch { return; }
        assertTrue(interest == (amount_ * ((rate_ * duration_) / 365 days)) / 1e18);
    }

    function testFuzz_run(uint256 amount_, uint256 rate_, uint256 duration_) public {
        _run(amount_, rate_, duration_);
    }

    receive() external payable {}
}
